@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Profile saved successfully!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="EditName" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="EditEmail" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
            </div>
        </div>
        <div class="col-md-4 text-center">
            <div class="avatar-preview mb-2">
                <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120"
                     onerror="this.style.display='none'" />
            </div>
            <small class="text-muted text-break">@Profile.AvatarUrl</small>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
            @(IsSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditName = "";
    private string EditEmail = "";
    private string EditBio = "";
    private bool IsSaving;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (!HasEdited)
            ResetFields();
    }

    private bool HasEdited;

    private void ResetFields()
    {
        EditName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditBio = Profile.Bio;
        HasEdited = false;
    }

    private async Task Save()
    {
        IsSaving = true;
        var updated = Profile with { DisplayName = EditName, Email = EditEmail, Bio = EditBio };
        await OnSave.InvokeAsync(updated);
        HasEdited = false;
        IsSaving = false;
        ShowSuccess = true;
    }

    private void Discard()
    {
        ResetFields();
        ShowSuccess = false;
    }
}

@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Notification preferences saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">General</h6>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">Muted Channels</h6>
        @foreach (var channel in AllChannels)
        {
            var channelId = $"channel-{channel}";
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@channelId"
                       checked="@MutedSet.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="@channelId">
                    #@channel @(MutedSet.Contains(channel) ? "(muted)" : "")
                </label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
        @(IsSaving ? "Saving…" : "Save Preferences")
    </button>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public IReadOnlyList<string> AllChannels { get; set; } = [];

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedSet = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted) MutedSet.Add(channel);
        else MutedSet.Remove(channel);
    }

    private async Task Save()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <hr />

    <div class="mb-4">
        <h6 class="fw-semibold mb-2">Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Security.TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </label>
            </div>
            <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                @(Security.TwoFactorEnabled ? "✓ Active" : "⚠ Inactive")
            </span>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <small class="text-muted mt-2 d-block">
                Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </small>
        }
    </div>

    <hr />

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrentSession = session == Security.Sessions.FirstOrDefault();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrentSession)
                                {
                                    <span class="badge bg-primary ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrentSession)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    <RevokeSessionDialog Visible="@(SessionToRevoke is not null)"
                         DeviceName="@(SessionToRevoke?.Device ?? "")"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? SessionToRevoke;

    private async Task HandleChangePassword((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }

    private void CancelRevoke() => SessionToRevoke = null;

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Appearance settings saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="theme-@theme" value="@theme"
                               checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="fs-@size" value="@size"
                               checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Language</h6>
                <select class="form-select" @bind="SelectedLanguage">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">
                        @(CompactMode ? "On" : "Off")
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
                @(IsSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-6">
            <h6 class="fw-semibold mb-2">Live Preview</h6>
            <div class="preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                <div class="preview-header">
                    <strong>Preview</strong>
                </div>
                <div class="preview-body @(CompactMode ? "compact" : "")">
                    <p class="preview-title">Sample Heading</p>
                    <p>This is how your content will look with the selected settings.</p>
                    <div class="d-flex gap-2">
                        <span class="badge bg-primary">Tag 1</span>
                        <span class="badge bg-secondary">Tag 2</span>
                    </div>
                    <small class="text-muted d-block mt-2">
                        Theme: @SelectedTheme · Font: @SelectedFontSize · Lang: @SelectedLanguage
                        @(CompactMode ? " · Compact" : "")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task Save()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-body.compact {
    padding: 0.5rem 1rem;
    line-height: 1.3;
}

.preview-body.compact p {
    margin-bottom: 0.25rem;
}

.preview-title {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

/* Light theme (default) */
.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background-color: #f8f9fa;
    border-bottom-color: #dee2e6;
}

/* Dark theme */
.preview-dark {
    background-color: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background-color: #181825;
    border-bottom-color: #45475a;
    color: #cdd6f4;
}

.preview-dark .text-muted {
    color: #a6adc8 !important;
}

/* System theme */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
    border-color: #6c757d;
}

.preview-system .preview-header {
    background: linear-gradient(135deg, #f8f9fa 50%, #181825 50%);
    border-bottom-color: #6c757d;
}

