<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Appearance settings saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="theme-@theme" value="@theme"
                               checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="fs-@size" value="@size"
                               checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Language</h6>
                <select class="form-select" @bind="SelectedLanguage">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">
                        @(CompactMode ? "On" : "Off")
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
                @(IsSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-6">
            <h6 class="fw-semibold mb-2">Live Preview</h6>
            <div class="preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                <div class="preview-header">
                    <strong>Preview</strong>
                </div>
                <div class="preview-body @(CompactMode ? "compact" : "")">
                    <p class="preview-title">Sample Heading</p>
                    <p>This is how your content will look with the selected settings.</p>
                    <div class="d-flex gap-2">
                        <span class="badge bg-primary">Tag 1</span>
                        <span class="badge bg-secondary">Tag 2</span>
                    </div>
                    <small class="text-muted d-block mt-2">
                        Theme: @SelectedTheme · Font: @SelectedFontSize · Lang: @SelectedLanguage
                        @(CompactMode ? " · Compact" : "")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task Save()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-body.compact {
    padding: 0.5rem 1rem;
    line-height: 1.3;
}

.preview-body.compact p {
    margin-bottom: 0.25rem;
}

.preview-title {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

/* Light theme (default) */
.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background-color: #f8f9fa;
    border-bottom-color: #dee2e6;
}

/* Dark theme */
.preview-dark {
    background-color: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background-color: #181825;
    border-bottom-color: #45475a;
    color: #cdd6f4;
}

.preview-dark .text-muted {
    color: #a6adc8 !important;
}

/* System theme */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
    border-color: #6c757d;
}

.preview-system .preview-header {
    background: linear-gradient(135deg, #f8f9fa 50%, #181825 50%);
    border-bottom-color: #6c757d;
}

