@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Profile saved successfully!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="EditName" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="EditEmail" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
            </div>
        </div>
        <div class="col-md-4 text-center">
            <div class="avatar-preview mb-2">
                <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120"
                     onerror="this.style.display='none'" />
            </div>
            <small class="text-muted text-break">@Profile.AvatarUrl</small>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
            @(IsSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditName = "";
    private string EditEmail = "";
    private string EditBio = "";
    private bool IsSaving;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (!HasEdited)
            ResetFields();
    }

    private bool HasEdited;

    private void ResetFields()
    {
        EditName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditBio = Profile.Bio;
        HasEdited = false;
    }

    private async Task Save()
    {
        IsSaving = true;
        var updated = Profile with { DisplayName = EditName, Email = EditEmail, Bio = EditBio };
        await OnSave.InvokeAsync(updated);
        HasEdited = false;
        IsSaving = false;
        ShowSuccess = true;
    }

    private void Discard()
    {
        ResetFields();
        ShowSuccess = false;
    }
}

