@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Notification preferences saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">General</h6>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">Muted Channels</h6>
        @foreach (var channel in AllChannels)
        {
            var channelId = $"channel-{channel}";
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@channelId"
                       checked="@MutedSet.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="@channelId">
                    #@channel @(MutedSet.Contains(channel) ? "(muted)" : "")
                </label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
        @(IsSaving ? "Saving…" : "Save Preferences")
    </button>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public IReadOnlyList<string> AllChannels { get; set; } = [];

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedSet = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted) MutedSet.Add(channel);
        else MutedSet.Remove(channel);
    }

    private async Task Save()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

