@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <hr />

    <div class="mb-4">
        <h6 class="fw-semibold mb-2">Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Security.TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </label>
            </div>
            <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                @(Security.TwoFactorEnabled ? "✓ Active" : "⚠ Inactive")
            </span>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <small class="text-muted mt-2 d-block">
                Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </small>
        }
    </div>

    <hr />

    <div class="mb-4">
        <h6 class="fw-semibold mb-3">Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrentSession = session == Security.Sessions.FirstOrDefault();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrentSession)
                                {
                                    <span class="badge bg-primary ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrentSession)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    <RevokeSessionDialog Visible="@(SessionToRevoke is not null)"
                         DeviceName="@(SessionToRevoke?.Device ?? "")"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? SessionToRevoke;

    private async Task HandleChangePassword((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }

    private void CancelRevoke() => SessionToRevoke = null;

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_356bc28618324beb91285381c717b8e7.Components.Pages.Settings
@using sv_356bc28618324beb91285381c717b8e7.Services

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
            Appearance settings saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="theme-@theme" value="@theme"
                               checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="fs-@size" value="@size"
                               checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Language</h6>
                <select class="form-select" @bind="SelectedLanguage">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <h6 class="fw-semibold mb-2">Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">
                        @(CompactMode ? "On" : "Off")
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
                @(IsSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-6">
            <h6 class="fw-semibold mb-2">Live Preview</h6>
            <div class="preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                <div class="preview-header">
                    <strong>Preview</strong>
                </div>
                <div class="preview-body @(CompactMode ? "compact" : "")">
                    <p class="preview-title">Sample Heading</p>
                    <p>This is how your content will look with the selected settings.</p>
                    <div class="d-flex gap-2">
                        <span class="badge bg-primary">Tag 1</span>
                        <span class="badge bg-secondary">Tag 2</span>
                    </div>
                    <small class="text-muted d-block mt-2">
                        Theme: @SelectedTheme · Font: @SelectedFontSize · Lang: @SelectedLanguage
                        @(CompactMode ? " · Compact" : "")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task Save()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
    }
}

